from . import models
from . import tools


def post_init_hook(env):
    from .tools.currency_names import load_currency_names
    from .tools.maintenance import ensure_default_systems
    ensure_default_systems(env)
    load_currency_names(env)


def uninstall_hook(env):
    """Leave nothing behind: the views generated by the Display Rules refer to a widget and to
    models of this module, and the settings are no longer used."""
    from .tools.names import GENERATED_VIEW_PREFIX
    env.cr.execute("DELETE FROM ir_ui_view WHERE name LIKE %s", (GENERATED_VIEW_PREFIX + '%',))
    env.cr.execute("DELETE FROM ir_config_parameter WHERE key LIKE 'number_to_words.%'")
    env.registry.clear_cache()
